-- =========================================================================
-- Private storage bucket for member photographs
-- =========================================================================
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'member-photos',
  'member-photos',
  false,
  5242880, -- 5 MB
  array['image/jpeg','image/png','image/webp']
)
on conflict (id) do nothing;

-- No public read. Signed URLs are generated by server-side functions only.
-- Do not create any anon SELECT policy on storage.objects for this bucket.